## 3. DATA TRANSFER OBJECTS (DTOs)

```typescript
// src/verification/dto/email-verification.dto.ts
import { IsEmail, IsString, MinLength, MaxLength } from 'class-validator';
import { PartialType } from '@nestjs/mapped-types';

export class SendEmailVerificationDto {
  @IsEmail()
  email: string;
}

export class VerifyEmailDto {
  @IsString()
  @MinLength(32)
  @MaxLength(500)
  token: string;
}

export class ResendEmailVerificationDto {
  @IsEmail()
  email?: string; // Optional; if not provided, use logged-in user's email
}

export class EmailVerificationResponseDto {
  success: boolean;
  message: string;
  expiresIn?: number;
}

// src/verification/dto/phone-verification.dto.ts
import { IsPhoneNumber, IsString, Length, Matches } from 'class-validator';

export class SendPhoneVerificationDto {
  @IsPhoneNumber(null) // Accepts any country code
  phoneNumber: string;
}

export class VerifyPhoneDto {
  @IsString()
  @Length(6, 6)
  @Matches(/^\d{6}$/)
  code: string;
}

export class PhoneVerificationResponseDto {
  success: boolean;
  message: string;
  expiresIn: number;
  maskedPhone: string;
}

// src/verification/dto/kyc.dto.ts
import { IsEnum, IsString, IsOptional, MaxLength } from 'class-validator';
