## 4. SERVICE LAYER (Business Logic)

```typescript
// src/verification/services/email-verification.service.ts
import { Injectable, HttpException, HttpStatus } from '@nestjs/common';
import { EmailVerificationRepository } from '../repositories/email-verification.repository';
import { UserService } from '@/users/services/user.service';
import { EmailService } from '@/common/services/email.service';
import { SendEmailVerificationDto, VerifyEmailDto } from '../dto/email-verification.dto';
import { EmailVerification } from '@prisma/client';

@Injectable()
export class EmailVerificationService {
  constructor(
    private emailVerificationRepo: EmailVerificationRepository,
    private userService: UserService,
    private emailService: EmailService,
  ) {}

  /**
   * Generate a cryptographically secure token for email verification
   * Includes expiry and is scoped to one-time use
   */
  async sendVerificationEmail(userId: string, email: string): Promise<void> {
    const user = await this.userService.findById(userId);
    if (!user) {
      throw new HttpException('User not found', HttpStatus.NOT_FOUND);
    }

    if (user.emailVerified && user.email === email) {
      throw new HttpException(
        'Email already verified',
        HttpStatus.CONFLICT,
      );
    }

    // Invalidate previous tokens for this user
    await this.emailVerificationRepo.invalidatePreviousTokens(userId);

    // Generate token and store
    const { token, tokenHash } = this.generateToken();
    const expiresAt = new Date(Date.now() + 30 * 60 * 1000); // 30 minutes

    await this.emailVerificationRepo.create({
      userId,
      email,
      token,
      tokenHash,
      expiresAt,
    });

    // Send email with verification link
    const verificationUrl = `${process.env.FRONTEND_URL}/auth/verify-email?token=${token}`;
    await this.emailService.sendVerificationEmail(email, verificationUrl);
  }

  /**
   * Verify email token and mark user's email as verified
   * Tokens are single-use and expire after 30 minutes
   */
  async verifyEmail(token: string): Promise<EmailVerification> {
    const verification = await this.emailVerificationRepo.findByToken(token);

    if (!verification) {
      throw new HttpException('Token not found', HttpStatus.NOT_FOUND);
    }

    if (new Date() > verification.expiresAt) {
      throw new HttpException('Token expired', HttpStatus.UNAUTHORIZED);
    }

    if (verification.status === 'VERIFIED') {
      throw new HttpException(
        'Token already used',
        HttpStatus.CONFLICT,
      );
    }

    // Mark as verified and update user
    const updated = await this.emailVerificationRepo.markAsVerified(
      verification.id,
    );

    await this.userService.updateEmailVerificationStatus(
      verification.userId,
      verification.email,
    );

    return updated;
  }

  /**
   * Resend verification email if previous token expired
   * Rate-limited to prevent abuse
   */
  async resendVerificationEmail(userId: string): Promise<void> {
    const user = await this.userService.findById(userId);
    if (!user) {
      throw new HttpException('User not found', HttpStatus.NOT_FOUND);
    }

    if (user.emailVerified) {
      throw new HttpException(
        'Email already verified',
        HttpStatus.CONFLICT,
      );
    }

    const lastSent = await this.emailVerificationRepo.getLastSentTime(userId);
    if (lastSent && new Date().getTime() - lastSent.getTime() < 60000) {
      // 1 minute rate limit
      throw new HttpException(
        'Too many requests',
        HttpStatus.TOO_MANY_REQUESTS,
      );
    }

    await this.sendVerificationEmail(userId, user.email);
  }

  private generateToken(): { token: string; tokenHash: string } {
    const crypto = require('crypto');
    const token = crypto.randomBytes(32).toString('hex');
    const tokenHash = crypto
      .createHash('sha256')
      .update(token)
      .digest('hex');
    return { token, tokenHash };
  }
}

// src/verification/services/phone-verification.service.ts
import { Injectable, HttpException, HttpStatus } from '@nestjs/common';
import { PhoneVerificationRepository } from '../repositories/phone-verification.repository';
import { UserService } from '@/users/services/user.service';
import { TwilioService } from '@/common/services/twilio.service';
import { SendPhoneVerificationDto, VerifyPhoneDto } from '../dto/phone-verification.dto';

@Injectable()
export class PhoneVerificationService {
  constructor(
    private phoneVerificationRepo: PhoneVerificationRepository,
    private userService: UserService,
    private twilioService: TwilioService,
  ) {}

  /**
   * Generate 6-digit code and send via SMS
   * Code expires in 10 minutes
   * Rate-limited to 3 attempts per 15 minutes
   */
  async sendVerificationCode(
    userId: string,
    phoneNumber: string,
  ): Promise<{ expiresIn: number; maskedPhone: string }> {
    const user = await this.userService.findById(userId);
    if (!user) {
      throw new HttpException('User not found', HttpStatus.NOT_FOUND);
    }

    if (user.phoneVerified && user.phoneNumber === phoneNumber) {
      throw new HttpException(
        'Phone already verified',
        HttpStatus.CONFLICT,
      );
    }

    // Check rate limit
    const recentAttempts =
      await this.phoneVerificationRepo.getRecentAttempts(userId);
    if (recentAttempts >= 3) {
      throw new HttpException(
        'Too many attempts. Try again later.',
        HttpStatus.TOO_MANY_REQUESTS,
      );
    }

    // Invalidate previous code
    await this.phoneVerificationRepo.invalidatePreviousCode(userId);

    // Generate 6-digit code
    const code = this.generateCode();
    const expiresAt = new Date(Date.now() + 10 * 60 * 1000); // 10 minutes

    const verification = await this.phoneVerificationRepo.create({
      userId,
      phoneNumber,
      verificationCode: code,
      expiresAt,
    });

    // Send via Twilio
    await this.twilioService.sendSms(
      phoneNumber,
      `Your verification code is: ${code}. Valid for 10 minutes.`,
    );

    const maskedPhone = this.maskPhoneNumber(phoneNumber);
    return { expiresIn: 600, maskedPhone };
  }

  /**
   * Verify phone code and mark phone as verified
   * Locked out after 3 failed attempts
   */
  async verifyPhoneCode(userId: string, code: string): Promise<void> {
    const verification =
      await this.phoneVerificationRepo.findActiveByUserId(userId);

    if (!verification) {
      throw new HttpException(
        'No active verification request',
        HttpStatus.NOT_FOUND,
      );
    }

    if (new Date() > verification.expiresAt) {
      throw new HttpException('Code expired', HttpStatus.UNAUTHORIZED);
    }

    if (verification.attempts >= verification.maxAttempts) {
      throw new HttpException(
        'Too many failed attempts. Request a new code.',
        HttpStatus.TOO_MANY_REQUESTS,
      );
    }

    if (verification.verificationCode !== code) {
      await this.phoneVerificationRepo.incrementAttempts(verification.id);
      throw new HttpException('Invalid code', HttpStatus.UNAUTHORIZED);
    }

    // Mark as verified
    await this.phoneVerificationRepo.markAsVerified(verification.id);
    await this.userService.updatePhoneVerificationStatus(
      userId,
      verification.phoneNumber,
    );
  }

  private generateCode(): string {
    return Math.floor(100000 + Math.random() * 900000).toString();
  }

  private maskPhoneNumber(phone: string): string {
    // E.g., "+12025551234" → "+1202***1234"
    return phone.replace(/(\d{4})(\d+)(\d{4})/, '$1***$3');
  }
}

// src/verification/services/kyc.service.ts
import { Injectable, HttpException, HttpStatus } from '@nestjs/common';
import { KycDocumentRepository } from '../repositories/kyc-document.repository';
import { UserService } from '@/users/services/user.service';
import { S3Service } from '@/common/services/s3.service';
import { UploadKycDocumentDto, RejectKycDto } from '../dto/kyc.dto';
import { KycDocument, KycVerificationStatus } from '@prisma/client';
import { Express } from 'express';

@Injectable()
export class KycService {
  constructor(
    private kycDocumentRepo: KycDocumentRepository,
    private userService: UserService,
    private s3Service: S3Service,
  ) {}

  /**
   * Upload KYC document to S3
   * Validates file type (image/PDF only), size (<10MB)
   * Scans for adult content / document validity
   */
  async uploadDocument(
    userId: string,
    file: Express.Multer.File,
    dto: UploadKycDocumentDto,
  ): Promise<KycDocument> {
    const user = await this.userService.findById(userId);
    if (!user) {
      throw new HttpException('User not found', HttpStatus.NOT_FOUND);
    }

    // Prevent re-upload if already approved
    const existingApproved =
      await this.kycDocumentRepo.findApprovedByUserId(userId);
    if (existingApproved) {
      throw new HttpException(
        'KYC already approved for this user',
        HttpStatus.CONFLICT,
      );
    }

    // Validate file
    this.validateFile(file);

    // Upload to S3
    const documentUrl = await this.s3Service.uploadFile(file, `kyc/${userId}`);

    // Store metadata
    const document = await this.kycDocumentRepo.create({
      userId,
      documentType: dto.documentType,
      documentUrl,
      fileSize: file.size,
      fileName: file.originalname,
      mimeType: file.mimetype,
      expiresAt: this.calculateDocumentExpiry(dto.documentType),
    });

    return document;
  }

  /**
   * Get KYC status for user including all documents
   */
  async getVerificationStatus(userId: string): Promise<{
    userId: string;
    kycVerified: boolean;
    documents: KycDocument[];
    canResubmit: boolean;
  }> {
    const user = await this.userService.findById(userId);
    if (!user) {
      throw new HttpException('User not found', HttpStatus.NOT_FOUND);
    }

    const documents = await this.kycDocumentRepo.findByUserId(userId);
    const rejectedDoc = documents.find((d) => d.status === 'REJECTED');

    return {
      userId,
      kycVerified: user.kycVerified,
      documents,
      canResubmit: !!rejectedDoc, // Can resubmit if any document was rejected
    };
  }

  /**
   * Delete a document if it's still PENDING
   * Cannot delete approved or verified documents
   */
  async deleteDocument(userId: string, documentId: string): Promise<void> {
    const document = await this.kycDocumentRepo.findById(documentId);
    if (!document || document.userId !== userId) {
      throw new HttpException('Document not found', HttpStatus.NOT_FOUND);
    }

    if (document.status !== 'PENDING') {
      throw new HttpException(
        'Cannot delete non-pending document',
        HttpStatus.FORBIDDEN,
      );
    }

    // Delete from S3
    await this.s3Service.deleteFile(document.documentUrl);

    // Delete from DB
    await this.kycDocumentRepo.delete(documentId);
  }

  /**
   * Resubmit after rejection
   * Can upload a different type or same type
   */
  async resubmitDocument(
    userId: string,
    file: Express.Multer.File,
    rejectedDocumentId: string,
    newDocumentType: string,
  ): Promise<KycDocument> {
    const rejectedDoc = await this.kycDocumentRepo.findById(
      rejectedDocumentId,
    );

    if (!rejectedDoc || rejectedDoc.userId !== userId) {
      throw new HttpException(
        'Original document not found',
        HttpStatus.NOT_FOUND,
      );
    }

    if (rejectedDoc.status !== 'REJECTED') {
      throw new HttpException(
        'Can only resubmit rejected documents',
        HttpStatus.CONFLICT,
      );
    }

    // Upload new document
    this.validateFile(file);
    const documentUrl = await this.s3Service.uploadFile(file, `kyc/${userId}`);

    // Create new document entry
    const newDocument = await this.kycDocumentRepo.create({
      userId,
      documentType: newDocumentType,
      documentUrl,
      fileSize: file.size,
      fileName: file.originalname,
      mimeType: file.mimetype,
      expiresAt: this.calculateDocumentExpiry(newDocumentType),
    });

    // Optionally: delete old file
    await this.s3Service.deleteFile(rejectedDoc.documentUrl);

    return newDocument;
  }

  /**
   * Admin: Approve KYC for a user
   * Transitions user to FULLY_VERIFIED (if email+phone already verified)
   * Triggers notification to user
   */
  async approveKyc(userId: string, adminId: string): Promise<void> {
    const documents = await this.kycDocumentRepo.findByUserId(userId);
    if (!documents.length) {
      throw new HttpException('No documents found', HttpStatus.NOT_FOUND);
    }

    // Mark latest PENDING document as approved
    const pendingDoc = documents.find((d) => d.status === 'PENDING');
    if (!pendingDoc) {
      throw new HttpException(
        'No pending documents to approve',
        HttpStatus.CONFLICT,
      );
    }

    await this.kycDocumentRepo.update(pendingDoc.id, {
      status: 'APPROVED',
      verifiedAt: new Date(),
      verifiedBy: adminId,
    });

    await this.userService.updateKycVerificationStatus(userId, true);
  }

  /**
   * Admin: Reject KYC with reason
   * User can resubmit after rejection
   * Triggers notification with rejection reason
   */
  async rejectKyc(
    userId: string,
    documentId: string,
    dto: RejectKycDto,
    adminId: string,
  ): Promise<void> {
    const document = await this.kycDocumentRepo.findById(documentId);
    if (!document || document.userId !== userId) {
      throw new HttpException('Document not found', HttpStatus.NOT_FOUND);
    }

    await this.kycDocumentRepo.update(documentId, {
      status: 'REJECTED',
      rejectionReason: dto.rejectionReason,
      verifiedBy: adminId,
      verifiedAt: new Date(),
    });

    // Notify user via email
    // await this.notificationService.sendKycRejectionEmail(userId, dto.rejectionReason);
  }

  /**
   * Get pending KYC verifications for admin dashboard
   * Paginated, oldest first
   */
  async getPendingVerifications(limit: number, offset: number) {
    return this.kycDocumentRepo.findPending(limit, offset);
  }

  private validateFile(file: Express.Multer.File): void {
    const MAX_SIZE = 10 * 1024 * 1024; // 10MB
    const ALLOWED_TYPES = ['image/jpeg', 'image/png', 'application/pdf'];

    if (file.size > MAX_SIZE) {
      throw new HttpException(
        `File size exceeds maximum of ${MAX_SIZE} bytes`,
        HttpStatus.PAYLOAD_TOO_LARGE,
      );
    }

    if (!ALLOWED_TYPES.includes(file.mimetype)) {
      throw new HttpException(
        'Invalid file type. Only JPEG, PNG, and PDF allowed.',
        HttpStatus.UNSUPPORTED_MEDIA_TYPE,
      );
    }
  }

  private calculateDocumentExpiry(documentType: string): Date | null {
    // Driver's license and passport expire
    // Utility bill doesn't expire
    if (documentType === 'DRIVER_LICENSE' || documentType === 'PASSPORT') {
      const expiry = new Date();
      expiry.setFullYear(expiry.getFullYear() + 5); // Typical 5-year validity
      return expiry;
    }
    return null;
  }
}

