import { Injectable, HttpException, HttpStatus } from '@nestjs/common';
import { UserService } from '@/users/services/user.service';
import { VerificationStatusResponseDto } from '../dto/verification-status.dto';

@Injectable()
export class VerificationService {
  private readonly KYC_HIGH_VALUE_THRESHOLD =
    parseInt(process.env.KYC_HIGH_VALUE_THRESHOLD || '500000', 10);

  constructor(private userService: UserService) {}

  /**
   * Get comprehensive verification status for user
   * Includes requirements based on their actions
   */
  async getFullVerificationStatus(
    userId: string,
  ): Promise<VerificationStatusResponseDto> {
    const user = await this.userService.findById(userId);
    if (!user) {
      throw new HttpException('User not found', HttpStatus.NOT_FOUND);
    }

    return {
      userId: user.id,
      email: user.email,
      emailVerified: user.emailVerified,
      emailVerifiedAt: user.emailVerifiedAt,
      phoneVerified: user.phoneVerified,
      phoneVerifiedAt: user.phoneVerifiedAt,
      kycVerified: user.kycVerified,
      kycVerifiedAt: user.kycVerifiedAt,
      verificationStatus: user.verificationStatus,
      requirements: {
        emailRequired: true,
        phoneRequired: user.role === 'SELLER', // Sellers must verify phone
        kycRequired: user.role === 'SELLER', // Sellers must complete KYC
        nextUnlockedFeature: this.getNextFeature(user),
      },
    };
  }

  /**
   * Enforce email verification (most endpoints)
   */
  async requireEmailVerification(userId: string): Promise<void> {
    const user = await this.userService.findById(userId);
    if (!user?.emailVerified) {
      throw new HttpException(
        'Email verification required',
        HttpStatus.FORBIDDEN,
      );
    }
  }

  /**
   * Enforce phone verification (sellers, messaging)
   */
  async requirePhoneVerification(userId: string): Promise<void> {
    const user = await this.userService.findById(userId);
    if (user?.role === 'SELLER' && !user.phoneVerified) {
      throw new HttpException(
        'Phone verification required for sellers',
        HttpStatus.FORBIDDEN,
      );
    }
  }

  /**
   * Enforce KYC verification for high-value transactions
   */
  async requireKycVerification(
    transactionValue: number,
    userId: string,
  ): Promise<void> {
    if (transactionValue > this.KYC_HIGH_VALUE_THRESHOLD) {
      const user = await this.userService.findById(userId);
      if (!user?.kycVerified) {
        throw new HttpException(
          `KYC verification required for transactions over $${this.KYC_HIGH_VALUE_THRESHOLD}`,
          HttpStatus.FORBIDDEN,
        );
      }
    }
  }

  private getNextFeature(user: any): string {
    if (!user.emailVerified) return 'browse_properties';
    if (!user.phoneVerified) return 'contact_sellers';
    if (!user.kycVerified) return 'high_value_transactions';
    return 'all_features_unlocked';
  }
}
