@Injectable()
export class EmailVerificationRepository {
  constructor(private prisma: PrismaService) {}

  async create(data: {
    userId: string;
    email: string;
    token: string;
    tokenHash: string;
    expiresAt: Date;
  }): Promise<EmailVerification> {
    return this.prisma.emailVerification.create({
      data: {
        userId: data.userId,
        email: data.email,
        token: data.token,
        tokenHash: data.tokenHash,
        expiresAt: data.expiresAt,
        status: 'PENDING',
      },
    });
  }

  async findByToken(token: string): Promise<EmailVerification | null> {
    return this.prisma.emailVerification.findUnique({
      where: { token },
    });
  }

  async findByUserId(userId: string): Promise<EmailVerification[]> {
    return this.prisma.emailVerification.findMany({
      where: { userId },
      orderBy: { createdAt: 'desc' },
    });
  }

  async markAsVerified(id: string): Promise<EmailVerification> {
    return this.prisma.emailVerification.update({
      where: { id },
      data: {
        status: 'VERIFIED',
        verifiedAt: new Date(),
      },
    });
  }

  async invalidatePreviousTokens(userId: string): Promise<void> {
    await this.prisma.emailVerification.updateMany({
      where: {
        userId,
        status: 'PENDING',
      },
      data: {
        status: 'EXPIRED',
      },
    });
  }

  async getLastSentTime(userId: string): Promise<Date | null> {
    const record = await this.prisma.emailVerification.findFirst({
      where: { userId },
      orderBy: { createdAt: 'desc' },
      select: { createdAt: true },
    });
    return record?.createdAt || null;
  }
