        status: 'PENDING',
      },
    });
  }

  async findByUserId(userId: string): Promise<KycDocument[]> {
    return this.prisma.kycDocument.findMany({
      where: { userId },
      orderBy: { uploadedAt: 'desc' },
    });
  }

  async findById(id: string): Promise<KycDocument | null> {
    return this.prisma.kycDocument.findUnique({
      where: { id },
    });
  }

  async findApprovedByUserId(userId: string): Promise<KycDocument | null> {
    return this.prisma.kycDocument.findFirst({
      where: {
        userId,
        status: 'APPROVED',
      },
    });
  }

  async update(
    id: string,
    data: Partial<KycDocument>,
  ): Promise<KycDocument> {
    return this.prisma.kycDocument.update({
      where: { id },
      data,
    });
  }

  async delete(id: string): Promise<void> {
    await this.prisma.kycDocument.delete({
      where: { id },
    });
  }

  async findPending(
    limit: number,
    offset: number,
  ): Promise<{ total: number; documents: KycDocument[] }> {
    const [documents, total] = await Promise.all([
      this.prisma.kycDocument.findMany({
        where: { status: 'PENDING' },
        orderBy: { uploadedAt: 'asc' },
        take: limit,
        skip: offset,
        include: { user: { select: { id: true, email: true } } },
      }),
      this.prisma.kycDocument.count({
        where: { status: 'PENDING' },
      }),
    ]);
    return { total, documents };
  }
}
