// Add to user.service.ts

async updateEmailVerificationStatus(
  userId: string,
  email: string,
): Promise<void> {
  await this.prisma.user.update({
    where: { id: userId },
    data: {
      email,
      emailVerified: true,
      emailVerifiedAt: new Date(),
      verificationStatus: await this.computeVerificationStatus(userId),
    },
  });

  // Trigger verification audit log
  await this.createAuditLog(userId, 'EMAIL_VERIFIED', { email });
}

async updatePhoneVerificationStatus(
  userId: string,
  phoneNumber: string,
): Promise<void> {
  await this.prisma.user.update({
    where: { id: userId },
    data: {
      phoneNumber,
      phoneVerified: true,
      phoneVerifiedAt: new Date(),
      verificationStatus: await this.computeVerificationStatus(userId),
    },
  });

  await this.createAuditLog(userId, 'PHONE_VERIFIED', { phoneNumber });
}

async updateKycVerificationStatus(
  userId: string,
  isVerified: boolean,
): Promise<void> {
  await this.prisma.user.update({
    where: { id: userId },
    data: {
      kycVerified: isVerified,
      kycVerifiedAt: isVerified ? new Date() : null,
      verificationStatus: await this.computeVerificationStatus(userId),
    },
  });

  await this.createAuditLog(userId, 'KYC_' + (isVerified ? 'APPROVED' : 'REJECTED'));
}

private async computeVerificationStatus(userId: string): Promise<UserVerificationStatus> {
  const user = await this.prisma.user.findUnique({
    where: { id: userId },
    select: { emailVerified: true, phoneVerified: true, kycVerified: true },
  });

  if (user.kycVerified) return 'FULLY_VERIFIED';
  if (user.phoneVerified) return 'PHONE_VERIFIED';
  if (user.emailVerified) return 'EMAIL_VERIFIED';
  return 'UNVERIFIED';
}

private async createAuditLog(
  userId: string,
  action: string,
  details?: any,
): Promise<void> {
  await this.prisma.verificationAuditLog.create({
    data: {
      userId,
      action,
      details: JSON.stringify(details),
    },
  });
}
