# Dispute Resolution System - Complete Design Spec

## 1. DATABASE SCHEMA (Prisma)

```prisma
// prisma/schema.prisma

enum DisputeStatus {
  OPEN
  UNDER_REVIEW
  MEDIATION
  RESOLVED
  CLOSED
  APPEALED
}

enum DisputeReason {
  PROPERTY_CONDITION
  MISREPRESENTATION
  PAYMENT_ISSUE
  DELIVERY_FAILURE
  SAFETY_CONCERN
  OTHER
}

enum EvidenceType {
  PHOTO
  DOCUMENT
  VIDEO_LINK
  MESSAGE_LINK
  OTHER
}

enum ResolutionType {
  REFUND_FULL
  REFUND_PARTIAL
  COMPENSATION_CREDIT
  REPLACEMENT
  NO_ACTION
  OTHER
}

model Dispute {
  id                    String                @id @default(cuid())
  transactionId         String                @unique
  transaction           Transaction           @relation(fields: [transactionId], references: [id], onDelete: Cascade)

  // Parties
  initiatorId           String
  initiator             User                  @relation("DisputeInitiator", fields: [initiatorId], references: [id])
  respondentId          String
  respondent            User                  @relation("DisputeRespondent", fields: [respondentId], references: [id])

  // Details
  reason                DisputeReason
  description           String                @db.Text
  status                DisputeStatus         @default(OPEN)

  // Resolution
  resolutionType        ResolutionType?
  resolutionDetails     String?               @db.Text
  resolvedAt            DateTime?
  resolvedById          String?
  resolvedBy            User?                 @relation("DisputeResolver", fields: [resolvedById], references: [id])

  // Auto-close tracking
  lastActivityAt        DateTime              @default(now())
  autoClosedAt          DateTime?

  // Appeal
  appealedAt            DateTime?
  appealReason          String?               @db.Text
  appealedById          String?
  appealedBy            User?                 @relation("DisputeAppealant", fields: [appealedById], references: [id])

  // Relations
  evidence              DisputeEvidence[]
  timeline              DisputeTimeline[]

  createdAt             DateTime              @default(now())
  updatedAt             DateTime              @updatedAt

  @@index([transactionId])
  @@index([initiatorId])
  @@index([respondentId])
  @@index([status])
  @@index([createdAt])
}

model DisputeEvidence {
  id                    String                @id @default(cuid())
  disputeId             String
  dispute               Dispute               @relation(fields: [disputeId], references: [id], onDelete: Cascade)

  // Submission
  submittedById         String
  submittedBy           User                  @relation(fields: [submittedById], references: [id])
  type                  EvidenceType

  // Content
  title                 String
  description           String?               @db.Text
  fileUrl               String?               // S3/Cloud URL
  videoUrl              String?               // YouTube, Vimeo, etc.
  messageSnippet        String?               @db.Text // For linked messages

  // Metadata
  uploadedAt            DateTime              @default(now())
  fileSize              Int?                  // bytes
  mimeType              String?

  createdAt             DateTime              @default(now())
  updatedAt             DateTime              @updatedAt

  @@index([disputeId])
  @@index([submittedById])
}

model DisputeTimeline {
  id                    String                @id @default(cuid())
  disputeId             String
  dispute               Dispute               @relation(fields: [disputeId], references: [id], onDelete: Cascade)

  action                String                // "status_changed", "evidence_submitted", "admin_action", "message_sent"
  statusFrom            DisputeStatus?
  statusTo              DisputeStatus?
  actedById             String?
  actedBy               User?                 @relation(fields: [actedById], references: [id])

  note                  String?               @db.Text

  createdAt             DateTime              @default(now())

  @@index([disputeId])
  @@index([createdAt])
}

// EXTEND existing models
model User {
  // ... existing fields ...

  // New dispute-related fields
  disputesInitiated     Dispute[]             @relation("DisputeInitiator")
  disputesResponded     Dispute[]             @relation("DisputeRespondent")
  disputesResolved      Dispute[]             @relation("DisputeResolver")
  disputesAppealed      Dispute[]             @relation("DisputeAppealant")

  evidenceSubmitted     DisputeEvidence[]
  timelineActions       DisputeTimeline[]

  // Dispute notification preference
  disputeNotifyEmail    Boolean               @default(true)
}

model Transaction {
  // ... existing fields ...

  // New dispute relation
  dispute               Dispute?
}
```

