## 4. SERVICE LAYER (Business Logic)

```typescript
// src/disputes/disputes.service.ts
import { Injectable, HttpException, HttpStatus, BadRequestException, ForbiddenException } from '@nestjs/common';
import { DisputesRepository } from './disputes.repository';
import { TransactionService } from '@/transactions/transactions.service';
import { UsersService } from '@/users/users.service';
import { CreateDisputeDto, SubmitEvidenceDto, ResolveDisputeDto, AppealDto, RequestInfoDto } from './dto';
import { EmailService } from '@/email/email.service';
import { DisputeStatus, DisputeReason, EvidenceType, ResolutionType } from '@prisma/client';

@Injectable()
export class DisputesService {
  constructor(
    private disputesRepo: DisputesRepository,
    private transactionsService: TransactionService,
    private usersService: UsersService,
    private emailService: EmailService,
  ) {}

  /**
   * Initiate a new dispute. Verify transaction exists, not already disputed,
