## 5. REPOSITORY LAYER (Data Access)

```typescript
// src/disputes/disputes.repository.ts
import { Injectable } from '@nestjs/common';
import { PrismaService } from '@/prisma/prisma.service';
import { Dispute, DisputeEvidence, DisputeTimeline, DisputeStatus } from '@prisma/client';
import { CreateDisputeDto, SubmitEvidenceDto } from './dto';

@Injectable()
export class DisputesRepository {
  constructor(private prisma: PrismaService) {}

  /**
   * Create a new dispute record.
   */
  async createDispute(data: {
    transactionId: string;
    initiatorId: string;
    respondentId: string;
    reason: string;
    description: string;
  }): Promise<Dispute> {
    try {
      return await this.prisma.dispute.create({
        data: {
          transactionId: data.transactionId,
          initiatorId: data.initiatorId,
          respondentId: data.respondentId,
          reason: data.reason,
          description: data.description,
          status: 'OPEN',
          lastActivityAt: new Date(),
        },
        include: {
          initiator: { select: { id: true, fullName: true, email: true } },
          respondent: { select: { id: true, fullName: true, email: true } },
        },
      });
    } catch (error) {
      throw new Error(`Failed to create dispute: ${error.message}`);
    }
  }

  /**
   * Find dispute by ID with all relations.
   */
  async findById(disputeId: string): Promise<Dispute | null> {
    return this.prisma.dispute.findUnique({
      where: { id: disputeId },
      include: {
        initiator: { select: { id: true, fullName: true, email: true, avatar: true } },
        respondent: { select: { id: true, fullName: true, email: true, avatar: true } },
        resolvedBy: { select: { id: true, fullName: true } },
        transaction: {
          include: {
            buyer: { select: { id: true, fullName: true } },
            seller: { select: { id: true, fullName: true } },
          },
        },
      },
    });
  }

  /**
   * Find disputes by initiatorId or respondentId.
   */
  async findByUserId(userId: string, skip: number, take: number, filters?: { status?: DisputeStatus; reason?: string }): Promise<{ disputes: Dispute[]; total: number }> {
    const where = {
      OR: [{ initiatorId: userId }, { respondentId: userId }],
      ...(filters?.status && { status: filters.status }),
      ...(filters?.reason && { reason: filters.reason }),
    };

    const [disputes, total] = await Promise.all([
      this.prisma.dispute.findMany({
        where,
        skip,
        take,
        orderBy: { createdAt: 'desc' },
        include: {
          initiator: { select: { id: true, fullName: true } },
          respondent: { select: { id: true, fullName: true } },
        },
      }),
      this.prisma.dispute.count({ where }),
    ]);

    return { disputes, total };
  }

  /**
   * Find all disputes (admin only). Paginated with filters.
   */
  async findAll(skip: number, take: number, filters?: { status?: DisputeStatus; reason?: string }): Promise<{ disputes: Dispute[]; total: number }> {
    const where = {
      ...(filters?.status && { status: filters.status }),
      ...(filters?.reason && { reason: filters.reason }),
    };

    const [disputes, total] = await Promise.all([
      this.prisma.dispute.findMany({
        where,
        skip,
        take,
        orderBy: { createdAt: 'desc' },
        include: {
          initiator: { select: { id: true, fullName: true, email: true } },
          respondent: { select: { id: true, fullName: true, email: true } },
          _count: { select: { evidence: true, timeline: true } },
        },
      }),
      this.prisma.dispute.count({ where }),
    ]);

    return { disputes, total };
  }

  /**
   * Update dispute status and lastActivityAt.
   */
  async updateStatus(disputeId: string, status: DisputeStatus): Promise<Dispute> {
    return this.prisma.dispute.update({
      where: { id: disputeId },
      data: {
        status,
        lastActivityAt: new Date(),
      },
    });
  }

  /**
   * Update dispute with resolution details.
   */
  async updateWithResolution(disputeId: string, data: {
    status: DisputeStatus;
    resolutionType: string;
    resolutionDetails?: string;
    resolvedById: string;
  }): Promise<Dispute> {
    return this.prisma.dispute.update({
      where: { id: disputeId },
      data: {
        status: data.status,
        resolutionType: data.resolutionType,
        resolutionDetails: data.resolutionDetails,
        resolvedById: data.resolvedById,
        resolvedAt: new Date(),
        lastActivityAt: new Date(),
      },
    });
  }

  /**
   * Record an appeal.
   */
  async recordAppeal(disputeId: string, appealReason: string, appealantId: string): Promise<Dispute> {
    return this.prisma.dispute.update({
      where: { id: disputeId },
      data: {
        status: 'APPEALED',
        appealedAt: new Date(),
        appealReason,
        appealedById: appealantId,
        lastActivityAt: new Date(),
      },
    });
  }

  /**
   * Auto-close inactive disputes.
   */
  async autoCloseDisputes(beforeDate: Date): Promise<{ count: number }> {
    const result = await this.prisma.dispute.updateMany({
      where: {
        status: 'OPEN',
        lastActivityAt: { lt: beforeDate },
      },
      data: {
        status: 'CLOSED',
        autoClosedAt: new Date(),
      },
    });
    return { count: result.count };
  }

  /**
   * Create evidence record.
   */
  async createEvidence(data: {
    disputeId: string;
    submittedById: string;
    type: string;
    title: string;
    description?: string;
    fileUrl?: string;
    videoUrl?: string;
    messageSnippet?: string;
    fileSize?: number;
    mimeType?: string;
  }): Promise<DisputeEvidence> {
    return this.prisma.disputeEvidence.create({
      data,
    });
  }

  /**
   * Get evidence for dispute.
   */
  async getEvidenceByDispute(disputeId: string, skip: number, take: number): Promise<{ evidence: DisputeEvidence[]; total: number }> {
    const [evidence, total] = await Promise.all([
      this.prisma.disputeEvidence.findMany({
        where: { disputeId },
        skip,
        take,
        orderBy: { uploadedAt: 'desc' },
        include: {
          submittedBy: { select: { id: true, fullName: true, avatar: true } },
        },
      }),
      this.prisma.disputeEvidence.count({ where: { disputeId } }),
    ]);

    return { evidence, total };
  }

  /**
   * Delete evidence.
   */
  async deleteEvidence(evidenceId: string): Promise<void> {
    await this.prisma.disputeEvidence.delete({
      where: { id: evidenceId },
    });
  }

  /**
   * Get specific evidence.
   */
  async findEvidenceById(evidenceId: string): Promise<DisputeEvidence | null> {
    return this.prisma.disputeEvidence.findUnique({
      where: { id: evidenceId },
      include: {
        submittedBy: { select: { id: true, fullName: true } },
      },
    });
  }

  /**
   * Create timeline entry.
   */
  async createTimelineEntry(data: {
    disputeId: string;
    action: string;
    statusFrom?: DisputeStatus;
    statusTo?: DisputeStatus;
    actedById?: string;
    note?: string;
  }): Promise<DisputeTimeline> {
    return this.prisma.disputeTimeline.create({
      data,
    });
  }

  /**
   * Get timeline for dispute.
   */
  async getTimeline(disputeId: string, skip: number, take: number): Promise<{ timeline: DisputeTimeline[]; total: number }> {
    const [timeline, total] = await Promise.all([
      this.prisma.disputeTimeline.findMany({
        where: { disputeId },
        skip,
        take,
        orderBy: { createdAt: 'desc' },
        include: {
          actedBy: { select: { id: true, fullName: true, avatar: true } },
        },
      }),
      this.prisma.disputeTimeline.count({ where: { disputeId } }),
    ]);

    return { timeline, total };
  }

  /**
   * Find dispute by transaction ID.
   */
  async findByTransactionId(transactionId: string): Promise<Dispute | null> {
    return this.prisma.dispute.findUnique({
      where: { transactionId },
    });
  }

  /**
   * Get dispute stats.
   */
  async getStats(): Promise<any> {
    const [byStatus, byReason, avgResolutionTime, totalDisputes] = await Promise.all([
      this.prisma.dispute.groupBy({
        by: ['status'],
        _count: true,
      }),
      this.prisma.dispute.groupBy({
        by: ['reason'],
        _count: true,
      }),
      this.prisma.$queryRaw`
        SELECT AVG(EXTRACT(DAY FROM "resolvedAt" - "createdAt")) as avg_days
        FROM "Dispute"
        WHERE "status" = 'RESOLVED'
      `,
      this.prisma.dispute.count(),
    ]);

    return {
      byStatus,
      byReason,
      avgResolutionTime,
      totalDisputes,
    };
  }
}
