## 1. DATABASE SCHEMA (Prisma)

```prisma
// enums.prisma (or inline)
enum ResourceType {
  USER
  PROPERTY
  MESSAGE
}

enum FlagStatus {
  PENDING
  RESOLVED
  DISMISSED
}

enum SuspensionStatus {
  ACTIVE
  LIFTED
  EXPIRED
}

// models/flag.prisma
model Flag {
  id            String   @id @default(cuid())
  resourceType  ResourceType
  resourceId    String   // FK to User, Property, or Message id

  reason        String   @db.VarChar(500) // Abuse, Spam, Fraud, Inappropriate, etc.
  description   String?  @db.Text // Optional detailed description

  status        FlagStatus @default(PENDING)
  flaggedBy     String   // Admin or system who flagged it
  flaggedAt     DateTime @default(now())

  resolvedBy    String?  // Admin who resolved it
  resolution    String?  @db.VarChar(500) // Action taken (suspended, deleted, approved, etc.)
  resolvedAt    DateTime?

  // For moderation queue sorting/filtering
  priority      Int @default(0) // 0=normal, 1=high (auto-flagged)

  // Audit trail
  metadata      String?  @db.Text // JSON stringified evidence (report count, etc.)
  createdAt     DateTime @default(now())
  updatedAt     DateTime @updatedAt

  @@index([resourceType, resourceId])
  @@index([status, flaggedAt])
  @@index([flaggedBy])
  @@unique([resourceType, resourceId, flaggedBy]) // Prevent duplicate flags from same admin
}

// models/user-suspension.prisma
model UserSuspension {
  id            String   @id @default(cuid())
  userId        String   @unique
  user          User     @relation(fields: [userId], references: [id], onDelete: Cascade)

  reason        String   @db.VarChar(500) // Auto-suspend (5 flags), Manual, etc.
  description   String?  @db.Text

  status        SuspensionStatus @default(ACTIVE)

  suspendedAt   DateTime @default(now())
  suspendedBy   String   // Admin id or "system"

  suspendedUntil DateTime? // NULL = permanent until manually lifted

  liftedAt      DateTime?
  liftedBy      String?  // Admin who lifted it
  liftReason    String?

  createdAt     DateTime @default(now())
  updatedAt     DateTime @updatedAt

  @@index([userId, status])
  @@index([status, suspendedAt])
}

// Extend existing User model
model User {
  // ... existing fields ...

  // NEW: Moderation fields
  flagCount         Int @default(0) // Denormalized for fast queries
  suspensionStatus  SuspensionStatus? // ACTIVE, LIFTED, EXPIRED (for quick checks)
  isSuspended       Boolean @default(false) // Convenience flag for queries

  // Relations
  flags             Flag[]
  suspension        UserSuspension?

  // ... rest of model ...
}

// Extend existing Property model
model Property {
  // ... existing fields ...

  // NEW: Moderation fields
  isFlagged         Boolean @default(false)
  flagReason        String?  @db.VarChar(500)
  flaggedAt         DateTime?

  flags             Flag[]

  // ... rest of model ...
}

// Message already related to Connection, so messages are queryable
// No new fields needed on Message itself
```

