## 4. SERVICE LAYER (Business Logic)

```typescript
// moderation.service.ts
import { Injectable, HttpException, HttpStatus, Logger } from '@nestjs/common';
import { Prisma } from '@prisma/client';
import { FlagRepository } from './flag.repo';
import { UserSuspensionRepository } from './user-suspension.repo';
import { UserRepository } from '@features/user/user.repo';
import { PropertyRepository } from '@features/property/property.repo';
import { NotificationService } from '@common/notification/notification.service';
import {
  CreateFlagDto,
  ResolveFlagDto,
  DismissFlagDto,
  FlagQueryDto,
} from './dto/flag.dto';
import {
  CreateUserSuspensionDto,
  LiftSuspensionDto,
} from './dto/user-suspension.dto';

const AUTO_SUSPEND_THRESHOLD = 5; // flags to auto-suspend
const FLAG_EXPIRY_DAYS = 90; // older flags don't count toward auto-suspend

@Injectable()
export class ModerationService {
  private readonly logger = new Logger(ModerationService.name);

  constructor(
    private readonly flagRepo: FlagRepository,
    private readonly suspensionRepo: UserSuspensionRepository,
    private readonly userRepo: UserRepository,
    private readonly propertyRepo: PropertyRepository,
    private readonly notificationService: NotificationService,
  ) {}

  /**
   * Flag a resource (user, property, or message).
   * If resource is a user and reaches threshold, trigger auto-suspend.
   */
  async flagResource(
    createFlagDto: CreateFlagDto,
    adminId: string,
  ): Promise<FlagResponseDto> {
    // Validate resource exists
    const resourceExists = await this.validateResourceExists(
      createFlagDto.resourceType,
      createFlagDto.resourceId,
    );
    if (!resourceExists) {
      throw new HttpException('Resource not found', HttpStatus.NOT_FOUND);
    }

    // Check if already flagged by this admin (prevent duplicates)
    const existing = await this.flagRepo.findUnique({
      resourceType: createFlagDto.resourceType,
      resourceId: createFlagDto.resourceId,
      flaggedBy: adminId,
    });
    if (existing) {
      throw new HttpException(
        'Resource already flagged by this admin',
        HttpStatus.CONFLICT,
      );
    }

    // Create flag
    const flag = await this.flagRepo.create(createFlagDto, adminId);

    // If flagging a USER, check for auto-suspend
    if (createFlagDto.resourceType === 'USER') {
      await this.checkAndAutoSuspend(createFlagDto.resourceId, adminId);
    }

    // If flagging a PROPERTY, update denormalized flag fields
    if (createFlagDto.resourceType === 'PROPERTY') {
      await this.propertyRepo.update(createFlagDto.resourceId, {
        isFlagged: true,
        flagReason: createFlagDto.reason,
        flaggedAt: new Date(),
      });
    }

    // Notify resource owner
    await this.notifyResourceFlagged(
      createFlagDto.resourceType,
      createFlagDto.resourceId,
    );

    return this.mapFlagToResponse(flag);
  }

  /**
   * Resolve a flag with an action (suspend user, delete property, etc).
   */
  async resolveFlag(
    flagId: string,
    resolveDto: ResolveFlagDto,
    adminId: string,
  ): Promise<FlagResponseDto> {
    const flag = await this.flagRepo.findById(flagId);
    if (!flag) {
      throw new HttpException('Flag not found', HttpStatus.NOT_FOUND);
    }

    if (flag.status !== 'PENDING') {
      throw new HttpException(
        'Only pending flags can be resolved',
        HttpStatus.CONFLICT,
      );
    }

    // Handle resolution action
    if (resolveDto.action === 'SUSPEND' && flag.resourceType === 'USER') {
      await this.createUserSuspension(
        flag.resourceId,
        {
          reason: `Manual suspension: ${resolveDto.resolution}`,
          suspendedUntil: null,
        },
        adminId,
      );
    }

    if (resolveDto.action === 'DELETE' && flag.resourceType === 'PROPERTY') {
      await this.propertyRepo.update(flag.resourceId, { status: 'DELETED' });
    }

    // Update flag status
    const updated = await this.flagRepo.update(flagId, {
      status: 'RESOLVED',
      resolution: resolveDto.resolution,
      resolvedBy: adminId,
      resolvedAt: new Date(),
    });

    // Notify resource owner of resolution
    await this.notifyFlagResolved(flag.resourceType, flag.resourceId);

    return this.mapFlagToResponse(updated);
  }

  /**
   * Dismiss a flag (false positive, no violation).
   */
  async dismissFlag(
    flagId: string,
    dismissDto: DismissFlagDto,
    adminId: string,
  ): Promise<FlagResponseDto> {
    const flag = await this.flagRepo.findById(flagId);
    if (!flag) {
      throw new HttpException('Flag not found', HttpStatus.NOT_FOUND);
    }

    const updated = await this.flagRepo.update(flagId, {
      status: 'DISMISSED',
      resolution: dismissDto.reason,
      resolvedBy: adminId,
      resolvedAt: new Date(),
    });

    return this.mapFlagToResponse(updated);
  }

  /**
   * List all flags with optional filtering.
   */
  async listFlags(queryDto: FlagQueryDto): Promise<PaginatedFlagResponseDto> {
    const { limit = 20, offset = 0 } = queryDto;

    const flags = await this.flagRepo.findMany(queryDto, limit, offset);
    const total = await this.flagRepo.countByQuery(queryDto);

    return {
      data: flags.map((f) => this.mapFlagToResponse(f)),
      total,
      offset,
      limit,
    };
  }

  /**
   * Get flag by ID with associated resource details.
   */
  async getFlag(flagId: string): Promise<FlagWithResourceDto> {
    const flag = await this.flagRepo.findById(flagId);
    if (!flag) {
      throw new HttpException('Flag not found', HttpStatus.NOT_FOUND);
    }

    // Load resource details
    const resource = await this.loadResource(flag.resourceType, flag.resourceId);

    return {
      ...this.mapFlagToResponse(flag),
      resource,
    };
  }

  /**
   * Create a user suspension.
   */
  async createUserSuspension(
    userId: string,
    createDto: CreateUserSuspensionDto,
    adminId: string,
  ): Promise<UserSuspensionResponseDto> {
    const user = await this.userRepo.findById(userId);
    if (!user) {
      throw new HttpException('User not found', HttpStatus.NOT_FOUND);
    }

    // Check if already suspended
    const existing = await this.suspensionRepo.findActiveByUserId(userId);
    if (existing && existing.status === 'ACTIVE') {
      throw new HttpException('User already suspended', HttpStatus.CONFLICT);
    }

    const suspension = await this.suspensionRepo.create(
      {
        userId,
        reason: createDto.reason,
        description: createDto.description,
        suspendedUntil: createDto.suspendedUntil,
      },
      adminId,
    );

    // Update user denormalized fields
    await this.userRepo.update(userId, {
      isSuspended: true,
      suspensionStatus: 'ACTIVE',
      flagCount: 0, // Reset on suspension
    });

    // Notify user
    await this.notificationService.notifyUserSuspended(
      userId,
      createDto.reason,
      createDto.suspendedUntil,
    );

    return this.mapSuspensionToResponse(suspension);
  }

  /**
   * Lift a user suspension.
   */
  async liftSuspension(
    userId: string,
    liftDto: LiftSuspensionDto,
    adminId: string,
  ): Promise<UserSuspensionResponseDto> {
    const suspension = await this.suspensionRepo.findActiveByUserId(userId);
    if (!suspension) {
      throw new HttpException('User has no active suspension', HttpStatus.NOT_FOUND);
    }

    const updated = await this.suspensionRepo.update(suspension.id, {
      status: 'LIFTED',
      liftedBy: adminId,
      liftedAt: new Date(),
      liftReason: liftDto.reason,
    });

    // Update user
    await this.userRepo.update(userId, {
      isSuspended: false,
      suspensionStatus: 'LIFTED',
    });

    // Notify user
    await this.notificationService.notifyUserUnsuspended(userId);

    return this.mapSuspensionToResponse(updated);
  }

  /**
   * Get suspension history for a user.
   */
  async getSuspensionHistory(
    userId: string,
    limit: number,
    offset: number,
  ): Promise<UserSuspensionHistoryDto> {
    const user = await this.userRepo.findById(userId);
    if (!user) {
      throw new HttpException('User not found', HttpStatus.NOT_FOUND);
    }

    const suspensions = await this.suspensionRepo.findByUserId(userId, limit, offset);
    const total = await this.suspensionRepo.countByUserId(userId);

    return {
      data: suspensions.map((s) => this.mapSuspensionToResponse(s)),
      total,
      offset,
      limit,
    };
  }

  /**
   * Unflag a property.
   */
  async unflagProperty(
    propertyId: string,
    reason: string,
  ): Promise<PropertyDto> {
    const property = await this.propertyRepo.findById(propertyId);
    if (!property) {
      throw new HttpException('Property not found', HttpStatus.NOT_FOUND);
    }

    const updated = await this.propertyRepo.update(propertyId, {
      isFlagged: false,
      flagReason: null,
      flaggedAt: null,
    });

    // Notify property owner
    await this.notificationService.notifyPropertyUnflagged(propertyId, reason);

    return this.mapPropertyToResponse(updated);
  }

  /**
   * Get moderation statistics.
   */
  async getModerationStats(
    dateFrom?: Date,
    dateTo?: Date,
  ): Promise<ModerationStatsDto> {
    const from = dateFrom || new Date(Date.now() - 30 * 24 * 60 * 60 * 1000);
    const to = dateTo || new Date();

    const stats = await this.flagRepo.getStats(from, to);

    return {
      totalFlags: stats.total,
      pendingFlags: stats.pending,
      resolvedFlags: stats.resolved,
      dismissedFlags: stats.dismissed,
      suspendedUsers: await this.suspensionRepo.countActive(),
      flagsByResourceType: stats.byResourceType,
      flagsByReason: stats.byReason,
      dateFrom: from,
      dateTo: to,
    };
  }

  // ===== PRIVATE HELPERS =====

  /**
   * Check if resource exists (user, property, or message).
   */
  private async validateResourceExists(
    resourceType: string,
    resourceId: string,
  ): Promise<boolean> {
    if (resourceType === 'USER') {
      return !!(await this.userRepo.findById(resourceId));
    }
    if (resourceType === 'PROPERTY') {
      return !!(await this.propertyRepo.findById(resourceId));
    }
    if (resourceType === 'MESSAGE') {
      // Assume messageRepo exists
      return !!(await this.messageRepo.findById(resourceId));
    }
    return false;
  }

  /**
   * If a user reaches flag threshold, auto-suspend them.
   */
  private async checkAndAutoSuspend(userId: string, adminId: string): Promise<void> {
    const recentFlagCount = await this.flagRepo.countRecentByResourceId(
      userId,
      FLAG_EXPIRY_DAYS,
    );

    if (recentFlagCount >= AUTO_SUSPEND_THRESHOLD) {
      this.logger.warn(
        `Auto-suspending user ${userId} due to ${recentFlagCount} flags`,
      );

      const suspension = await this.suspensionRepo.create(
        {
          userId,
          reason: `Auto-suspend: ${recentFlagCount} flags in ${FLAG_EXPIRY_DAYS} days`,
          suspendedUntil: null,
        },
        'system',
      );

      await this.userRepo.update(userId, {
        isSuspended: true,
        suspensionStatus: 'ACTIVE',
      });

      await this.notificationService.notifyAutoSuspended(
        userId,
        recentFlagCount,
      );
    }
  }

  /**
   * Load full resource details (user, property, or message).
   */
  private async loadResource(resourceType: string, resourceId: string): Promise<any> {
    if (resourceType === 'USER') {
      return this.userRepo.findById(resourceId);
    }
    if (resourceType === 'PROPERTY') {
      return this.propertyRepo.findById(resourceId);
    }
    if (resourceType === 'MESSAGE') {
      return this.messageRepo.findById(resourceId);
    }
    return null;
  }

  /**
   * Notify resource owner that resource was flagged.
   */
  private async notifyResourceFlagged(
    resourceType: string,
    resourceId: string,
  ): Promise<void> {
    if (resourceType === 'USER') {
      await this.notificationService.notifyUserFlagged(resourceId);
    } else if (resourceType === 'PROPERTY') {
      const property = await this.propertyRepo.findById(resourceId);
      if (property) {
        await this.notificationService.notifyPropertyFlagged(property.sellerId);
      }
    } else if (resourceType === 'MESSAGE') {
      const message = await this.messageRepo.findById(resourceId);
      if (message) {
        await this.notificationService.notifyMessageFlagged(message.senderId);
      }
    }
  }

  /**
   * Notify resource owner of flag resolution.
   */
  private async notifyFlagResolved(
    resourceType: string,
    resourceId: string,
  ): Promise<void> {
    if (resourceType === 'USER') {
      await this.notificationService.notifyFlagResolved(resourceId);
    } else if (resourceType === 'PROPERTY') {
      const property = await this.propertyRepo.findById(resourceId);
      if (property) {
        await this.notificationService.notifyFlagResolved(property.sellerId);
      }
    }
  }

  /**
   * Map Prisma Flag to response DTO.
   */
  private mapFlagToResponse(flag: any): FlagResponseDto {
    return {
      id: flag.id,
      resourceType: flag.resourceType,
      resourceId: flag.resourceId,
      reason: flag.reason,
      description: flag.description,
      status: flag.status,
      flaggedBy: flag.flaggedBy,
      flaggedAt: flag.flaggedAt,
      resolvedBy: flag.resolvedBy,
      resolution: flag.resolution,
      resolvedAt: flag.resolvedAt,
      priority: flag.priority,
      metadata: flag.metadata ? JSON.parse(flag.metadata) : null,
    };
  }

  /**
   * Map Prisma UserSuspension to response DTO.
   */
  private mapSuspensionToResponse(suspension: any): UserSuspensionResponseDto {
    return {
      id: suspension.id,
      userId: suspension.userId,
      reason: suspension.reason,
      description: suspension.description,
      status: suspension.status,
      suspendedAt: suspension.suspendedAt,
      suspendedUntil: suspension.suspendedUntil,
      suspendedBy: suspension.suspendedBy,
      liftedAt: suspension.liftedAt,
      liftedBy: suspension.liftedBy,
      liftReason: suspension.liftReason,
    };
  }
}
