// flag.repo.ts
import { Injectable, Logger } from '@nestjs/common';
import { PrismaService } from '@common/prisma/prisma.service';
import { Flag, ResourceType, FlagStatus } from '@prisma/client';
import { RepoError } from '@common/errors/repo.error';

@Injectable()
export class FlagRepository {
  private readonly logger = new Logger(FlagRepository.name);

  constructor(private readonly prisma: PrismaService) {}

  /**
   * Create a new flag.
   */
  async create(
    data: {
      resourceType: ResourceType;
      resourceId: string;
      reason: string;
      description?: string;
    },
    flaggedBy: string,
  ): Promise<Flag> {
    try {
      return await this.prisma.flag.create({
        data: {
          ...data,
          flaggedBy,
          status: 'PENDING',
        },
      });
    } catch (error) {
      this.logger.error(`Failed to create flag: ${error.message}`);
      throw new RepoError('Could not create flag', error);
    }
  }

  /**
   * Find flag by ID.
   */
  async findById(id: string): Promise<Flag | null> {
    try {
      return await this.prisma.flag.findUnique({ where: { id } });
    } catch (error) {
      this.logger.error(`Failed to find flag: ${error.message}`);
      throw new RepoError('Could not find flag', error);
    }
  }

  /**
   * Find flag by resource and flaggedBy (unique constraint).
   */
  async findUnique(
    resourceType: ResourceType,
    resourceId: string,
    flaggedBy: string,
  ): Promise<Flag | null> {
    try {
      return await this.prisma.flag.findUnique({
        where: {
          resourceType_resourceId_flaggedBy: { resourceType, resourceId, flaggedBy },
        },
      });
    } catch (error) {
      this.logger.error(`Failed to find unique flag: ${error.message}`);
      throw new RepoError('Could not find flag', error);
    }
  }

  /**
   * Find many flags with filtering and pagination.
   */
  async findMany(
    query: {
      status?: FlagStatus;
      resourceType?: ResourceType;
      sortBy?: string;
      sortOrder?: 'ASC' | 'DESC';
    },
    limit: number,
    offset: number,
  ): Promise<Flag[]> {
    try {
      const where: any = {};
      if (query.status) where.status = query.status;
      if (query.resourceType) where.resourceType = query.resourceType;

      const orderBy: any = {};
      const sortBy = query.sortBy || 'flaggedAt';
      orderBy[sortBy] = query.sortOrder || 'DESC';

      return await this.prisma.flag.findMany({
        where,
        orderBy,
        take: limit,
        skip: offset,
      });
    } catch (error) {
      this.logger.error(`Failed to find many flags: ${error.message}`);
      throw new RepoError('Could not find flags', error);
    }
  }

  /**
   * Count flags matching query.
   */
  async countByQuery(query: {
    status?: FlagStatus;
    resourceType?: ResourceType;
  }): Promise<number> {
    try {
      const where: any = {};
      if (query.status) where.status = query.status;
      if (query.resourceType) where.resourceType = query.resourceType;

      return await this.prisma.flag.count({ where });
    } catch (error) {
      this.logger.error(`Failed to count flags: ${error.message}`);
      throw new RepoError('Could not count flags', error);
    }
  }

  /**
   * Count recent flags for a resource (used for auto-suspend check).
   */
  async countRecentByResourceId(resourceId: string, days: number): Promise<number> {
    try {
      const since = new Date(Date.now() - days * 24 * 60 * 60 * 1000);
      return await this.prisma.flag.count({
        where: {
          resourceId,
          flaggedAt: { gte: since },
          status: 'PENDING',
        },
      });
    } catch (error) {
      this.logger.error(`Failed to count recent flags: ${error.message}`);
      throw new RepoError('Could not count flags', error);
    }
  }

  /**
   * Update a flag.
   */
  async update(id: string, data: Partial<Flag>): Promise<Flag> {
    try {
      return await this.prisma.flag.update({
        where: { id },
        data,
      });
    } catch (error) {
      this.logger.error(`Failed to update flag: ${error.message}`);
      throw new RepoError('Could not update flag', error);
    }
  }

  /**
   * Delete a flag (rare, mostly for cleanup).
   */
  async delete(id: string): Promise<Flag> {
    try {
      return await this.prisma.flag.delete({ where: { id } });
    } catch (error) {
      this.logger.error(`Failed to delete flag: ${error.message}`);
      throw new RepoError('Could not delete flag', error);
    }
  }

  /**
   * Get moderation statistics.
   */
  async getStats(dateFrom: Date, dateTo: Date): Promise<any> {
    try {
      const where = { flaggedAt: { gte: dateFrom, lte: dateTo } };

      const [total, pending, resolved, dismissed] = await Promise.all([
        this.prisma.flag.count({ where }),
        this.prisma.flag.count({ where: { ...where, status: 'PENDING' } }),
        this.prisma.flag.count({ where: { ...where, status: 'RESOLVED' } }),
        this.prisma.flag.count({ where: { ...where, status: 'DISMISSED' } }),
      ]);

      // Get breakdown by resource type
      const byResourceType = await this.prisma.flag.groupBy({
        by: ['resourceType'],
        where,
        _count: true,
      });

      // Get breakdown by reason
      const byReason = await this.prisma.flag.groupBy({
        by: ['reason'],
        where,
        _count: true,
      });

      return {
        total,
        pending,
        resolved,
        dismissed,
        byResourceType: Object.fromEntries(
          byResourceType.map((r) => [r.resourceType, r._count]),
        ),
        byReason: Object.fromEntries(
          byReason.map((r) => [r.reason, r._count]),
        ),
      };
    } catch (error) {
      this.logger.error(`Failed to get stats: ${error.message}`);
      throw new RepoError('Could not get stats', error);
    }
  }
}
