// moderation.controller.ts
import {
  Controller,
  Get,
  Post,
  Patch,
  Param,
  Body,
  Query,
  UseGuards,
  HttpCode,
  HttpStatus,
} from '@nestjs/common';
import { JwtAuthGuard } from '@common/auth/jwt-auth.guard';
import { RolesGuard } from '@common/auth/roles.guard';
import { Roles } from '@common/auth/roles.decorator';
import { CurrentUser } from '@common/auth/current-user.decorator';
import { UserPayload } from '@common/auth/auth.types';
import { ModerationService } from './moderation.service';
import {
  CreateFlagDto,
  ResolveFlagDto,
  DismissFlagDto,
  FlagQueryDto,
  FlagResponseDto,
  PaginatedFlagResponseDto,
} from './dto/flag.dto';
import {
  CreateUserSuspensionDto,
  LiftSuspensionDto,
  UserSuspensionResponseDto,
  UserSuspensionHistoryDto,
} from './dto/user-suspension.dto';
import { ModerationStatsDto, ModerationStatsQueryDto } from './dto/moderation-stats.dto';

@Controller('admin/moderation')
@UseGuards(JwtAuthGuard, RolesGuard)
@Roles('ADMIN')
export class ModerationController {
  constructor(private readonly moderationService: ModerationService) {}

  // ===== Flag Management =====

  @Post('flags')
  @HttpCode(HttpStatus.CREATED)
  async createFlag(
    @Body() createFlagDto: CreateFlagDto,
    @CurrentUser() user: UserPayload,
  ): Promise<FlagResponseDto> {
    return this.moderationService.flagResource(createFlagDto, user.id);
  }

  @Get('queue')
  async listFlags(
    @Query() queryDto: FlagQueryDto,
  ): Promise<PaginatedFlagResponseDto> {
    return this.moderationService.listFlags(queryDto);
  }

  @Get('flags/:flagId')
  async getFlag(@Param('flagId') flagId: string): Promise<any> {
    return this.moderationService.getFlag(flagId);
  }

  @Patch('flags/:flagId/resolve')
  async resolveFlag(
    @Param('flagId') flagId: string,
    @Body() resolveDto: ResolveFlagDto,
    @CurrentUser() user: UserPayload,
  ): Promise<FlagResponseDto> {
    return this.moderationService.resolveFlag(flagId, resolveDto, user.id);
  }

  @Patch('flags/:flagId/dismiss')
  async dismissFlag(
    @Param('flagId') flagId: string,
    @Body() dismissDto: DismissFlagDto,
    @CurrentUser() user: UserPayload,
  ): Promise<FlagResponseDto> {
    return this.moderationService.dismissFlag(flagId, dismissDto, user.id);
  }

  // ===== User Suspension =====

  @Post('users/:userId/suspend')
  @HttpCode(HttpStatus.CREATED)
  async suspendUser(
    @Param('userId') userId: string,
    @Body() createSuspensionDto: CreateUserSuspensionDto,
    @CurrentUser() user: UserPayload,
  ): Promise<UserSuspensionResponseDto> {
    return this.moderationService.createUserSuspension(
      userId,
      createSuspensionDto,
      user.id,
    );
  }

  @Get('users/:userId/suspension')
  async getUserSuspension(
    @Param('userId') userId: string,
  ): Promise<UserSuspensionResponseDto> {
    // Service method to get current suspension
    return this.moderationService.getUserActiveSuspension(userId);
  }

  @Patch('users/:userId/suspension/lift')
  async liftSuspension(
    @Param('userId') userId: string,
    @Body() liftDto: LiftSuspensionDto,
    @CurrentUser() user: UserPayload,
  ): Promise<UserSuspensionResponseDto> {
    return this.moderationService.liftSuspension(userId, liftDto, user.id);
  }

  @Get('users/:userId/suspension-history')
  async getSuspensionHistory(
    @Param('userId') userId: string,
    @Query('limit') limit = 50,
    @Query('offset') offset = 0,
  ): Promise<UserSuspensionHistoryDto> {
    return this.moderationService.getSuspensionHistory(
      userId,
      Math.min(limit, 100),
      offset,
    );
  }

  // ===== Property Moderation =====

  @Get('properties/:propertyId/flags')
  async getPropertyFlags(@Param('propertyId') propertyId: string): Promise<any> {
    return this.moderationService.getPropertyFlags(propertyId);
  }

  @Patch('properties/:propertyId/unflag')
  async unflagProperty(
    @Param('propertyId') propertyId: string,
    @Body('reason') reason: string,
  ): Promise<any> {
    return this.moderationService.unflagProperty(propertyId, reason);
  }

  // ===== Statistics =====

  @Get('stats')
  async getModerationStats(
    @Query() queryDto: ModerationStatsQueryDto,
  ): Promise<ModerationStatsDto> {
    return this.moderationService.getModerationStats(
      queryDto.dateFrom,
      queryDto.dateTo,
    );
  }
}
