## 1. DATABASE SCHEMA (Prisma)

```prisma
// schema.prisma

enum AuditResourceType {
  USER
  PROPERTY
  CONNECTION
  OFFER
  TRANSACTION
  VIEWING
  REVIEW
  ADMIN_ACTION
  DISPUTE
}

enum AuditActionType {
  CREATE
  UPDATE
  DELETE
  ACCEPT
  REJECT
  RESPOND
  INITIATE_PAYMENT
  CONFIRM_PAYMENT
  CREATE_DISPUTE
  RESOLVE_DISPUTE
  SUSPEND_ACCOUNT
  REACTIVATE_ACCOUNT
  EXPORT_DATA
  BULK_UPDATE
}

model AuditLog {
  id                String              @id @default(cuid())
  resourceType      AuditResourceType
  resourceId        String              // UUID of the resource being audited
  action            AuditActionType
  actor             User                @relation("ActorAuditLogs", fields: [actorId], references: [id], onDelete: Cascade)
  actorId           String
  details           Json?               // arbitrary metadata (e.g., reason for rejection, dispute notes)
  changesBefore     Json?               // snapshot of fields before update {fieldName: oldValue, ...}
  changesAfter      Json?               // snapshot of fields after update {fieldName: newValue, ...}
  ipAddress         String?
  userAgent         String?
  createdAt         DateTime            @default(now())

  @@index([resourceType, resourceId]) // Query by resource type & ID
  @@index([actorId])                   // Query by who performed the action
  @@index([createdAt])                 // Query by date range
  @@index([resourceType, createdAt])   // Combine filters
  @@index([action])                    // Query by action type
  @@map("audit_logs")
}

// Extend existing User model:
model User {
  // ... existing fields ...
  auditLogsCreated    AuditLog[]    @relation("ActorAuditLogs")
  createdAt           DateTime      @default(now())
  updatedAt           DateTime      @updatedAt
  // ... rest of fields ...
}
```

