## 4. SERVICE LAYER (Business Logic)

```typescript
// audit-log.service.ts

import { Injectable, BadRequestException, NotFoundException } from '@nestjs/common';
import { AuditLogRepository } from './audit-log.repository';
import { UserRepository } from '@users/user.repository';
import {
  AuditResourceType,
  AuditActionType,
  AuditLog,
  Prisma,
} from '@prisma/client';
import {
  GetAuditLogsQueryDto,
  CreateAuditLogInternalDto,
  AuditLogResponseDto,
  AuditLogStatsResponseDto,
  ExportAuditLogsDto,
  ExportJobStatusResponseDto,
} from './audit-log.dto';

@Injectable()
export class AuditLogService {
  constructor(
    private readonly auditLogRepo: AuditLogRepository,
    private readonly userRepo: UserRepository,
    private readonly exportService: AuditLogExportService,
  ) {}

  /**
   * Create an audit log entry (called internally by middleware/services)
   * Never exposed via HTTP directly; always called from within business logic
   */
  async logAction(
    input: CreateAuditLogInternalDto,
  ): Promise<AuditLogResponseDto> {
    // Verify actor exists
    const actor = await this.userRepo.findById(input.actorId);
    if (!actor) {
      throw new BadRequestException(`Actor user ${input.actorId} not found`);
    }

    // Persist to immutable audit log
    const log = await this.auditLogRepo.create({
      resourceType: input.resourceType,
      resourceId: input.resourceId,
      action: input.action,
      actorId: input.actorId,
      details: input.details,
      changesBefore: input.changesBefore,
      changesAfter: input.changesAfter,
      ipAddress: input.ipAddress,
      userAgent: input.userAgent,
    });

    return this.toResponseDto(log, actor);
  }

  /**
   * Query audit logs with filters, pagination
   * Admin endpoint; returns decorated response with pagination metadata
   */
  async findMany(
    filters: GetAuditLogsQueryDto,
  ): Promise<{ data: AuditLogResponseDto[]; pagination: any }> {
    const where: Prisma.AuditLogWhereInput = {};

    if (filters.resourceType) where.resourceType = filters.resourceType;
    if (filters.action) where.action = filters.action;
    if (filters.actorId) where.actorId = filters.actorId;
    if (filters.resourceId) where.resourceId = filters.resourceId;

    // Date range filter
    if (filters.startDate || filters.endDate) {
      where.createdAt = {};
      if (filters.startDate)
        where.createdAt.gte = new Date(filters.startDate);
      if (filters.endDate) where.createdAt.lte = new Date(filters.endDate);
    }

    const [logs, total] = await Promise.all([
      this.auditLogRepo.findMany({
        where,
        skip: filters.skip,
        take: filters.take,
        orderBy: { createdAt: 'desc' },
      }),
      this.auditLogRepo.count(where),
    ]);

    // Enrich with actor data
    const enrichedLogs = await Promise.all(
      logs.map(async (log) => {
        const actor = await this.userRepo.findById(log.actorId);
        return this.toResponseDto(log, actor);
      }),
    );

    return {
      data: enrichedLogs,
      pagination: {
        total,
        skip: filters.skip,
        take: filters.take,
      },
    };
  }

  /**
   * Get audit trail for a specific resource (transaction, property, etc.)
   * Commonly called to show "who did what" on a resource detail page
   */
  async findByResource(
    resourceType: AuditResourceType,
    resourceId: string,
    skip: number = 0,
    take: number = 25,
  ): Promise<{ data: AuditLogResponseDto[]; pagination: any }> {
    const [logs, total] = await Promise.all([
      this.auditLogRepo.findMany({
        where: { resourceType, resourceId },
        skip,
        take,
        orderBy: { createdAt: 'desc' },
      }),
      this.auditLogRepo.count({ resourceType, resourceId }),
    ]);

    const enrichedLogs = await Promise.all(
      logs.map(async (log) => {
        const actor = await this.userRepo.findById(log.actorId);
        return this.toResponseDto(log, actor);
      }),
    );

    return {
      data: enrichedLogs,
      pagination: { total, skip, take },
    };
  }

  /**
   * Get audit logs for a transaction (endpoint-level convenience)
   * Business logic validates requester can access this transaction
   */
  async getTransactionAuditTrail(
    transactionId: string,
    skip: number = 0,
    take: number = 25,
  ): Promise<any> {
    // Caller's controller has already validated requester's permission
    return this.findByResource(
      AuditResourceType.TRANSACTION,
      transactionId,
      skip,
      take,
    );
  }

  /**
   * Get audit logs for a property
   */
  async getPropertyAuditTrail(
    propertyId: string,
    skip: number = 0,
    take: number = 25,
  ): Promise<any> {
    return this.findByResource(
      AuditResourceType.PROPERTY,
      propertyId,
      skip,
      take,
    );
  }

  /**
   * Aggregate statistics: action counts, resource type distribution, top actors
   * For admin dashboard KPI cards
   */
  async getStatistics(
    startDate?: Date,
    endDate?: Date,
  ): Promise<AuditLogStatsResponseDto> {
    const where: Prisma.AuditLogWhereInput = {};
    if (startDate || endDate) {
      where.createdAt = {};
      if (startDate) where.createdAt.gte = startDate;
      if (endDate) where.createdAt.lte = endDate;
    }

    const [total, logs, topActors] = await Promise.all([
      this.auditLogRepo.count(where),
      this.auditLogRepo.findMany({ where }),
      this.auditLogRepo.aggregateByActor(where),
    ]);

    // Count by action type
    const actionCounts = {} as Record<AuditActionType, number>;
    const resourceCounts = {} as Record<AuditResourceType, number>;

    logs.forEach((log) => {
      actionCounts[log.action] = (actionCounts[log.action] || 0) + 1;
      resourceCounts[log.resourceType] =
        (resourceCounts[log.resourceType] || 0) + 1;
    });

    return {
      totalLogs: total,
      logsInDateRange: logs.length,
      actionCounts,
      resourceTypeCounts: resourceCounts,
      topActors,
      dateRange: { startDate: startDate || new Date(0), endDate: endDate || new Date() },
    };
  }

  /**
   * Initiate async export of audit logs to PDF
   * Returns job ID for client to poll on completion
   */
  async initiateExport(
    input: ExportAuditLogsDto,
  ): Promise<{ jobId: string; status: string; estimatedCompletionSeconds: number; downloadUrl: string }> {
    // Validate date range
    const start = new Date(input.startDate);
    const end = new Date(input.endDate);
    if (end < start) {
      throw new BadRequestException('endDate must be after startDate');
    }

    const daysDiff = (end.getTime() - start.getTime()) / (1000 * 60 * 60 * 24);
    if (daysDiff > 90) {
      throw new BadRequestException(
        'Date range cannot exceed 90 days; use multiple exports',
      );
    }

    // Queue export job (returns immediately)
    const jobId = await this.exportService.queueExport({
      resourceType: input.resourceType,
      actorId: input.actorId,
      startDate: start,
      endDate: end,
      format: input.format,
      includeDetails: input.includeDetails,
    });

    // Estimate completion time based on log count
    const count = await this.auditLogRepo.countInRange(start, end);
    const estimatedSeconds = Math.ceil(count / 1000) * 10; // rough estimate

    return {
      jobId,
      status: 'queued',
      estimatedCompletionSeconds,
      downloadUrl: `/admin/audit-logs/export/${jobId}/download`,
    };
  }

  /**
   * Check status of async export job
   */
  async getExportStatus(jobId: string): Promise<ExportJobStatusResponseDto> {
    const job = await this.exportService.getJobStatus(jobId);
    if (!job) {
      throw new NotFoundException(`Export job ${jobId} not found`);
    }
    return job;
  }

  /**
   * Download completed export (streaming)
   * Returns file stream or throws 404/410 if not ready/expired
   */
  async downloadExport(
    jobId: string,
  ): Promise<{
    stream: NodeJS.ReadableStream;
    filename: string;
    contentType: string;
  }> {
    const job = await this.exportService.getJobStatus(jobId);
    if (!job) {
      throw new NotFoundException(`Export job ${jobId} not found`);
    }
    if (job.status !== 'completed') {
      throw new BadRequestException(
        `Export job ${jobId} is ${job.status}, not ready for download`,
      );
    }

    return this.exportService.downloadExport(jobId);
  }

  // ========== PRIVATE HELPERS ==========

  private toResponseDto(log: AuditLog, actor: any): AuditLogResponseDto {
    return {
      id: log.id,
      resourceType: log.resourceType,
      resourceId: log.resourceId,
      action: log.action,
      actor: {
        id: actor.id,
        fullName: actor.fullName,
        email: actor.email,
        role: actor.role,
      },
      details: log.details,
      changesBefore: log.changesBefore,
      changesAfter: log.changesAfter,
      ipAddress: log.ipAddress,
      userAgent: log.userAgent,
      createdAt: log.createdAt,
    };
  }
}

