## 5. REPOSITORY LAYER (Data Access)

```typescript
// audit-log.repository.ts

import { Injectable } from '@nestjs/common';
import { PrismaService } from '@common/prisma/prisma.service';
import { AuditLog, Prisma, AuditResourceType } from '@prisma/client';

@Injectable()
export class AuditLogRepository {
  constructor(private readonly prisma: PrismaService) {}

  /**
   * Insert audit log (immutable insert-only)
   */
  async create(data: Prisma.AuditLogCreateInput): Promise<AuditLog> {
    try {
      return await this.prisma.auditLog.create({ data });
    } catch (error) {
      throw new Error(`Failed to create audit log: ${error.message}`);
    }
  }

  /**
   * Query audit logs with filters
   */
  async findMany(args: Prisma.AuditLogFindManyArgs): Promise<AuditLog[]> {
    try {
      return await this.prisma.auditLog.findMany(args);
    } catch (error) {
      throw new Error(`Failed to query audit logs: ${error.message}`);
    }
  }

  /**
   * Get single audit log by ID
   */
  async findById(id: string): Promise<AuditLog | null> {
    try {
      return await this.prisma.auditLog.findUnique({ where: { id } });
    } catch (error) {
      throw new Error(`Failed to fetch audit log ${id}: ${error.message}`);
    }
  }

  /**
   * Count audit logs matching criteria (for pagination)
   */
  async count(where: Prisma.AuditLogWhereInput): Promise<number> {
    try {
      return await this.prisma.auditLog.count({ where });
    } catch (error) {
      throw new Error(`Failed to count audit logs: ${error.message}`);
    }
  }

  /**
   * Count logs within date range
   */
  async countInRange(startDate: Date, endDate: Date): Promise<number> {
    return this.count({
      createdAt: { gte: startDate, lte: endDate },
    });
  }

  /**
   * Aggregate action counts by actor for analytics
   */
  async aggregateByActor(
    where: Prisma.AuditLogWhereInput,
  ): Promise<
    Array<{
      userId: string;
      fullName: string;
      actionCount: number;
    }>
  > {
    try {
      const result = await this.prisma.auditLog.groupBy({
        by: ['actorId'],
        where,
        _count: { id: true },
        orderBy: { _count: { id: 'desc' } },
        take: 10,
      });

      // Enrich with user names (would fetch User in calling service)
      return result.map((r) => ({
        userId: r.actorId,
        fullName: '', // to be populated by service
        actionCount: r._count.id,
      }));
    } catch (error) {
      throw new Error(`Failed to aggregate audit logs: ${error.message}`);
    }
  }

  /**
   * Get audit logs for a specific resource (transaction, property, etc.)
   */
  async findByResourceId(
    resourceType: AuditResourceType,
    resourceId: string,
  ): Promise<AuditLog[]> {
    return this.findMany({
      where: { resourceType, resourceId },
      orderBy: { createdAt: 'desc' },
    });
  }

  /**
   * No update or delete methods — audit logs are immutable
   */
}
