```typescript
// property.service.ts (existing)

export class PropertyService {
  constructor(
    private readonly propertyRepo: PropertyRepository,
    private readonly auditLogService: AuditLogService,
  ) {}

  async createProperty(
    dto: CreatePropertyDto,
    sellerId: string,
    auditMetadata: any,
  ): Promise<Property> {
    const property = await this.propertyRepo.create({ ...dto, sellerId });

    await this.auditLogService.logAction({
      resourceType: AuditResourceType.PROPERTY,
      resourceId: property.id,
      action: AuditActionType.CREATE,
      actorId: sellerId,
      details: { title: property.title, price: property.price },
      ipAddress: auditMetadata.ipAddress,
      userAgent: auditMetadata.userAgent,
    });

    return property;
  }

  async updateProperty(
    propertyId: string,
    dto: UpdatePropertyDto,
    userId: string,
    auditMetadata: any,
  ): Promise<Property> {
    const before = await this.propertyRepo.findById(propertyId);
    const after = await this.propertyRepo.update(propertyId, dto);

    // Capture only changed fields
    const changes = this.diffObjects(before, after);

    await this.auditLogService.logAction({
      resourceType: AuditResourceType.PROPERTY,
      resourceId: propertyId,
      action: AuditActionType.UPDATE,
      actorId: userId,
      changesBefore: changes.before,
      changesAfter: changes.after,
      ipAddress: auditMetadata.ipAddress,
      userAgent: auditMetadata.userAgent,
    });

    return after;
  }

  private diffObjects(before: any, after: any): { before: any; after: any } {
    const changesBefore = {};
    const changesAfter = {};

    const allKeys = new Set([...Object.keys(before), ...Object.keys(after)]);
    allKeys.forEach((key) => {
      if (before[key] !== after[key]) {
        changesBefore[key] = before[key];
        changesAfter[key] = after[key];
      }
    });

    return { before: changesBefore, after: changesAfter };
  }
}
