// connection.service.ts (existing)

export class ConnectionService {
  constructor(
    private readonly connectionRepo: ConnectionRepository,
    private readonly auditLogService: AuditLogService,
  ) {}

  async acceptConnection(
    connectionId: string,
    userId: string,
    auditMetadata: any,
  ): Promise<Connection> {
    const before = await this.connectionRepo.findById(connectionId);
    const after = await this.connectionRepo.update(connectionId, {
      status: 'ACCEPTED',
    });

    await this.auditLogService.logAction({
      resourceType: AuditResourceType.CONNECTION,
      resourceId: connectionId,
      action: AuditActionType.ACCEPT,
      actorId: userId,
      changesBefore: { status: before.status },
      changesAfter: { status: after.status },
      ipAddress: auditMetadata.ipAddress,
      userAgent: auditMetadata.userAgent,
    });

    return after;
  }

  async rejectConnection(
    connectionId: string,
    userId: string,
    reason: string,
    auditMetadata: any,
  ): Promise<Connection> {
    const before = await this.connectionRepo.findById(connectionId);
    const after = await this.connectionRepo.update(connectionId, {
      status: 'REJECTED',
    });

    await this.auditLogService.logAction({
      resourceType: AuditResourceType.CONNECTION,
      resourceId: connectionId,
      action: AuditActionType.REJECT,
      actorId: userId,
      details: { reason },
      changesBefore: { status: before.status },
      changesAfter: { status: after.status },
      ipAddress: auditMetadata.ipAddress,
      userAgent: auditMetadata.userAgent,
    });

    return after;
  }
}
