```typescript
// transaction.service.ts (existing)

export class TransactionService {
  constructor(
    private readonly transactionRepo: TransactionRepository,
    private readonly auditLogService: AuditLogService,
    private readonly stripeService: StripeService,
  ) {}

  async initiatePayment(
    transactionId: string,
    userId: string,
    auditMetadata: any,
  ): Promise<{ clientSecret: string }> {
    const transaction = await this.transactionRepo.findById(transactionId);

    const paymentIntent = await this.stripeService.createPaymentIntent({
      amount: transaction.finalPrice,
      currency: 'usd',
    });

    await this.transactionRepo.update(transactionId, {
      stripePaymentIntentId: paymentIntent.id,
      status: 'PAYMENT_PENDING',
    });

    await this.auditLogService.logAction({
      resourceType: AuditResourceType.TRANSACTION,
      resourceId: transactionId,
      action: AuditActionType.INITIATE_PAYMENT,
      actorId: userId,
      details: { stripePaymentIntentId: paymentIntent.id },
      ipAddress: auditMetadata.ipAddress,
      userAgent: auditMetadata.userAgent,
    });

    return { clientSecret: paymentIntent.client_secret };
  }

  async confirmPayment(
    transactionId: string,
    stripePaymentIntentId: string,
    auditMetadata: any,
  ): Promise<Transaction> {
    const before = await this.transactionRepo.findById(transactionId);

    // Verify with Stripe
    const paymentIntent = await this.stripeService.getPaymentIntent(
      stripePaymentIntentId,
    );
    if (paymentIntent.status !== 'succeeded') {
      throw new BadRequestException('Payment intent not succeeded');
    }

    const after = await this.transactionRepo.update(transactionId, {
      status: 'COMPLETED',
    });

    // Identify who confirmed (buyer or payment system webhook)
    const actorId = paymentIntent.metadata?.userId || 'system';

    await this.auditLogService.logAction({
      resourceType: AuditResourceType.TRANSACTION,
      resourceId: transactionId,
      action: AuditActionType.CONFIRM_PAYMENT,
      actorId,
      details: {
        stripeEventId: paymentIntent.id,
        amount: paymentIntent.amount_received / 100,
      },
      changesBefore: { status: before.status },
      changesAfter: { status: after.status },
      ipAddress: auditMetadata?.ipAddress,
      userAgent: auditMetadata?.userAgent,
    });

    return after;
  }
}
```

### 8.7 Admin Service: Log Admin Actions

```typescript
// admin.service.ts (new or existing)

export class AdminService {
  constructor(
    private readonly userRepo: UserRepository,
    private readonly auditLogService: AuditLogService,
  ) {}

  async suspendUser(
    userId: string,
    adminId: string,
    reason: string,
    auditMetadata: any,
  ): Promise<User> {
    const before = await this.userRepo.findById(userId);
    const after = await this.userRepo.update(userId, { status: 'SUSPENDED' });

    await this.auditLogService.logAction({
      resourceType: AuditResourceType.USER,
      resourceId: userId,
      action: AuditActionType.SUSPEND_ACCOUNT,
      actorId: adminId,
      details: { reason },
      changesBefore: { status: before.status },
      changesAfter: { status: after.status },
      ipAddress: auditMetadata.ipAddress,
      userAgent: auditMetadata.userAgent,
    });

    return after;
  }

  async reactivateUser(
    userId: string,
    adminId: string,
    auditMetadata: any,
  ): Promise<User> {
    const before = await this.userRepo.findById(userId);
    const after = await this.userRepo.update(userId, { status: 'ACTIVE' });

    await this.auditLogService.logAction({
      resourceType: AuditResourceType.USER,
      resourceId: userId,
      action: AuditActionType.REACTIVATE_ACCOUNT,
      actorId: adminId,
      changesBefore: { status: before.status },
      changesAfter: { status: after.status },
      ipAddress: auditMetadata.ipAddress,
      userAgent: auditMetadata.userAgent,
    });

    return after;
  }
}
```

### 8.8 Updates to Controller Base Classes

All state-changing endpoints must pass `auditMetadata` from request:

```typescript
// Example: PropertyController.post (create)

@Post()
@UseGuards(JwtAuthGuard)
async createProperty(
  @Body() dto: CreatePropertyDto,
  @CurrentUser() user: UserEntity,
  @Req() req: Request,
): Promise<PropertyResponseDto> {
  const auditMetadata = req['auditMetadata']; // Set by middleware
  const property = await this.propertyService.createProperty(
    dto,
    user.id,
    auditMetadata,
  );
  return this.toDto(property);
}
