import { Queue, QueueScheduler } from 'bull';
import { Injectable } from '@nestjs/common';
import { BullModule } from '@nestjs/bull';

@Injectable()
export class AuditLogQueue {
  constructor(
    @InjectQueue('audit-log') private auditQueue: Queue,
  ) {}

  async enqueueLog(input: CreateAuditLogInternalDto): Promise<void> {
    await this.auditQueue.add(input, {
      removeOnComplete: true,
